// "23:40" → 분. 새벽 5시 전은 다음날로 보고 +24시간 (예: 00:08 → 1448)
export function toMin(s) {
  const [h, m] = s.split(':').map(Number)
  const v = h * 60 + m
  return v < 300 ? v + 1440 : v
}

// a ~ b 시각까지 step분 간격 배차
function D(a, b, step) {
  const out = []
  for (let t = toMin(a); t <= toMin(b); t += step) out.push(t)
  return out
}

// 한 구간: 이름, 출발 시각들, 탑승 분, 환승 도보 분, 노선, 색
function L(name, deps, ride, xfer, line, c) {
  return { name, deps, ride, xfer: xfer || 0, line: line || '', c }
}

// 한 경로: 이름, 첫 승차 장소, 거기까지 도보(m), 구간들
function R(name, board, walkM, legs) {
  return { name, board, walkM, legs }
}

